def adapt(path):
    from rdkit import Chem
    from rdkit.Chem import Descriptors, rdMolDescriptors, Crippen, Lipinski
    import re

    try:
        with open(path, 'r', encoding='utf-8', errors='replace') as f:
            raw = f.read(100000)
    except Exception as e:
        return {'text': 'Could not read molecule file: ' + str(e)}

    mol = None
    source = ''
    for line in raw.splitlines():
        line = line.strip()
        if not line or line.startswith('#'):
            continue
        candidates = [line, line.split()[0]]
        for candidate in candidates:
            try:
                mol = Chem.MolFromSmiles(candidate)
            except Exception:
                mol = None
            if mol is not None and mol.GetNumAtoms():
                source = candidate
                break
        if mol is not None and mol.GetNumAtoms():
            break
    if mol is None:
        return {'text': 'Could not parse a SMILES molecule from the file. File content: ' + raw[:1000]}

    lines = ['Input SMILES: ' + source]
    try:
        lines.append('Canonical isomeric SMILES: ' + Chem.MolToSmiles(mol, canonical=True, isomericSmiles=True))
        lines.append('Molecular formula: ' + rdMolDescriptors.CalcMolFormula(mol))
        lines.append('Molecular weight: %.2f g/mol; exact mass: %.4f Da' % (Descriptors.MolWt(mol), Descriptors.ExactMolWt(mol)))
        lines.append('Heavy atoms: %d; formal charge: %+d; disconnected components: %d' % (mol.GetNumHeavyAtoms(), Chem.GetFormalCharge(mol), len(Chem.GetMolFrags(mol))))
        lines.append('Rings: %d total, %d aromatic; rotatable bonds: %d' % (rdMolDescriptors.CalcNumRings(mol), rdMolDescriptors.CalcNumAromaticRings(mol), Lipinski.NumRotatableBonds(mol)))
        lines.append('Hydrogen-bond donors: %d; acceptors: %d; topological polar surface area: %.1f A^2; calculated logP: %.2f' % (Lipinski.NumHDonors(mol), Lipinski.NumHAcceptors(mol), rdMolDescriptors.CalcTPSA(mol), Crippen.MolLogP(mol)))
    except Exception:
        pass

    patterns = [
        ('aldehyde', '[CX3H1](=O)[#6]'),
        ('ketone', '[#6][CX3](=O)[#6]'),
        ('carboxylic acid', '[CX3](=O)[OX2H1]'),
        ('ester', '[CX3](=O)[OX2][#6]'),
        ('amide', '[CX3](=O)[NX3]'),
        ('phenol', '[OX2H][c]'),
        ('alcohol', '[OX2H][CX4]'),
        ('aryl ether', '[c][OX2][#6]'),
        ('aliphatic ether', '[CX4][OX2][CX4]'),
        ('amine', '[NX3;H0,H1,H2;!$(NC=O)]'),
        ('nitrile', '[CX2]#N'),
        ('nitro', '[N+](=O)[O-]'),
        ('thiol', '[SX2H]'),
        ('sulfide', '[#6][SX2][#6]'),
        ('alkene', '[CX3]=[CX3]'),
        ('alkyne', '[CX2]#[CX2]'),
        ('halogen substituent', '[F,Cl,Br,I]')
    ]
    groups = []
    for name, smarts in patterns:
        try:
            query = Chem.MolFromSmarts(smarts)
            matches = mol.GetSubstructMatches(query, uniquify=True)
            if matches:
                groups.append('%s (%d)' % (name, len(matches)))
        except Exception:
            pass
    if groups:
        lines.append('Detected structural groups: ' + ', '.join(groups) + '.')
    try:
        rings = mol.GetRingInfo().AtomRings()
        for ring in rings:
            atoms = [mol.GetAtomWithIdx(i) for i in ring]
            if len(ring) == 6 and all(a.GetIsAromatic() and a.GetSymbol() == 'C' for a in atoms):
                substituents = []
                ring_set = set(ring)
                for pos, idx in enumerate(ring):
                    atom = mol.GetAtomWithIdx(idx)
                    for neighbor in atom.GetNeighbors():
                        if neighbor.GetIdx() not in ring_set and neighbor.GetAtomicNum() > 1:
                            substituents.append((pos, neighbor.GetSymbol(), neighbor.GetIdx()))
                if len(substituents) >= 2:
                    pairs = []
                    for i in range(len(substituents)):
                        for j in range(i + 1, len(substituents)):
                            a, b = substituents[i], substituents[j]
                            d = abs(a[0] - b[0])
                            d = min(d, 6 - d)
                            if d:
                                pairs.append('%s and %s substituents separated by %d ring bond%s' % (a[1], b[1], d, '' if d == 1 else 's'))
                    if pairs:
                        lines.append('Benzene ring substitution: ' + '; '.join(pairs) + '.')
    except Exception:
        pass
    return {'text': '\n'.join(lines)[:4000]}
